"""
DomainPrioritizer — ranks domains by knowledge hunger score.
hunger_score = query_frequency × (1 - coverage) × staleness_factor
"""

import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional, Union

ROOT = Path(__file__).resolve().parents[4]
VECTORS_DB = ROOT / ".claude" / "data" / "knowledge-distillation" / "decision-vectors.db"

VALID_DIMENSIONS = [
    "failure_rates",
    "unit_economics",
    "competitive_landscape",
    "moat_patterns",
    "founder_paths",
    "timing_windows",
    "regulatory_risks",
    "compounding_mechanisms",
]


def _staleness_factor(last_fed: Optional[str]) -> float:
    """Returns 1.0 if never fed, scales up with age (max 2.0)."""
    if not last_fed:
        return 2.0
    try:
        fed_dt = datetime.fromisoformat(last_fed)
        if fed_dt.tzinfo is None:
            fed_dt = fed_dt.replace(tzinfo=timezone.utc)
        now = datetime.now(timezone.utc)
        days_old = (now - fed_dt).days
        return min(2.0, 1.0 + days_old / 90.0)
    except (ValueError, TypeError):
        return 1.5


class DomainPrioritizer:
    def __init__(self, db_path: Optional[Path] = None):
        self.db_path = db_path or VECTORS_DB

    def prioritize(
        self,
        query_freq: Optional[Union[dict, str, Path]] = None,
    ) -> list[tuple[str, str, float]]:
        """
        Returns sorted list of (domain, dimension, hunger_score) tuples.
        query_freq: dict of {domain: count}, file path to JSON, or None (equal priority).
        """
        freq_map = self._load_freq(query_freq)
        coverage_rows = self._load_coverage()

        if not coverage_rows:
            return self._cold_start(freq_map)

        results = []
        for row in coverage_rows:
            domain = row["domain"]
            dims_total = max(1, row["dimensions_total"] or len(VALID_DIMENSIONS))
            dims_filled = row["dimensions_filled"] or 0
            avg_conf = row["avg_confidence"] or 0.0
            last_fed = row["last_fed"]

            coverage = min(1.0, dims_filled / dims_total)
            staleness = _staleness_factor(last_fed)
            freq = freq_map.get(domain, 1)

            base_score = freq * (1.0 - coverage) * staleness

            for dim in VALID_DIMENSIONS:
                dim_score = round(base_score * (1.0 - avg_conf), 4)
                results.append((domain, dim, dim_score))

        results.sort(key=lambda x: x[2], reverse=True)
        return results

    def _cold_start(self, freq_map: dict) -> list[tuple[str, str, float]]:
        """Equal priority when no domain_coverage rows exist."""
        domains = list(freq_map.keys()) if freq_map else ["general"]
        results = []
        for domain in domains:
            for dim in VALID_DIMENSIONS:
                results.append((domain, dim, 1.0))
        return results

    def _load_freq(self, query_freq) -> dict:
        if query_freq is None:
            return {}
        if isinstance(query_freq, dict):
            return query_freq
        path = Path(query_freq)
        if path.exists():
            import json
            return json.loads(path.read_text(encoding="utf-8"))
        return {}

    def _load_coverage(self) -> list[dict]:
        if not self.db_path.exists():
            return []
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                conn.row_factory = sqlite3.Row
                rows = conn.execute("""
                    SELECT domain, query_count, dimensions_total, dimensions_filled,
                           avg_confidence, last_fed, last_gap_check
                    FROM domain_coverage
                """).fetchall()
                return [dict(r) for r in rows]
        except sqlite3.OperationalError:
            return []

"""
ClaimVerifier — cross-checks ParsedClaims against existing KB.
Detects duplicates (fuzzy), contradictions, magnitude outliers, stale sources.
"""

import json
import sqlite3
import statistics
from datetime import datetime, timezone
from difflib import SequenceMatcher
from pathlib import Path
from typing import Optional

from .claim_parser import ParsedClaim

ROOT = Path(__file__).resolve().parents[4]
VECTORS_DB = ROOT / ".claude" / "data" / "knowledge-distillation" / "decision-vectors.db"

FUZZY_THRESHOLD = 0.85
STALENESS_DAYS = 180
SIGMA_FLAG = 3.0


def _days_old(date_str: Optional[str]) -> Optional[int]:
    if not date_str:
        return None
    for fmt in ("%Y-%m-%d", "%Y-%m", "%Y"):
        try:
            dt = datetime.strptime(date_str[:len(fmt)], fmt)
            dt = dt.replace(tzinfo=timezone.utc)
            return (datetime.now(timezone.utc) - dt).days
        except ValueError:
            continue
    return None


def _similarity(a: str, b: str) -> float:
    return SequenceMatcher(None, a.lower().strip(), b.lower().strip()).ratio()


class ClaimVerifier:
    def __init__(self, db_path: Optional[Path] = None):
        self.db_path = db_path or VECTORS_DB

    def verify(self, claims: list[ParsedClaim]) -> dict:
        """
        Returns:
          verified_claims: list[ParsedClaim] — passed all checks (possibly downgraded)
          contradictions: list[dict] — {new_claim, existing_fact, reason}
          duplicates_merged: list[dict] — {claim, matched_existing, similarity}
        """
        kb_facts = self._load_kb_facts()
        kb_values = self._load_kb_values()

        verified: list[ParsedClaim] = []
        contradictions: list[dict] = []
        duplicates_merged: list[dict] = []

        for claim in claims:
            # 1. Duplicate detection
            dup = self._check_duplicate(claim, kb_facts)
            if dup:
                duplicates_merged.append(dup)
                continue

            # 2. Contradiction detection
            contra = self._check_contradiction(claim, kb_facts)
            if contra:
                contradictions.append(contra)
                claim.confidence = max(0.0, claim.confidence - 0.2)
                claim.zone_tag = "?"

            # 3. Magnitude outlier (3σ)
            if claim.value is not None:
                dim_values = kb_values.get(claim.dimension, [])
                if len(dim_values) >= 5:
                    mean = statistics.mean(dim_values)
                    stdev = statistics.stdev(dim_values)
                    if stdev > 0 and abs(claim.value - mean) > SIGMA_FLAG * stdev:
                        claim.zone_tag = "?"
                        claim.confidence = min(claim.confidence, 0.4)

            # 4. Source freshness
            age = _days_old(claim.source_date)
            if age is not None and age > STALENESS_DAYS:
                if claim.zone_tag == "K":
                    claim.zone_tag = "T"
                claim.confidence = max(0.0, claim.confidence - 0.1)

            verified.append(claim)

        return {
            "verified_claims": verified,
            "contradictions": contradictions,
            "duplicates_merged": duplicates_merged,
        }

    def _check_duplicate(self, claim: ParsedClaim, kb_facts: list[str]) -> Optional[dict]:
        for existing in kb_facts:
            sim = _similarity(claim.fact, existing)
            if sim >= FUZZY_THRESHOLD:
                return {
                    "claim": claim.fact,
                    "matched_existing": existing,
                    "similarity": round(sim, 3),
                }
        return None

    def _check_contradiction(self, claim: ParsedClaim, kb_facts: list[str]) -> Optional[dict]:
        """Simple heuristic: same topic + opposing numeric signal."""
        claim_lower = claim.fact.lower()
        for existing in kb_facts:
            if _similarity(claim.fact, existing) < 0.4:
                continue
            existing_lower = existing.lower()
            # detect opposing magnitude words
            opposing = [
                ("high", "low"), ("increase", "decrease"), ("growing", "declining"),
                ("profitable", "unprofitable"), ("success", "fail"),
            ]
            for pos, neg in opposing:
                if pos in claim_lower and neg in existing_lower:
                    return {"new_claim": claim.fact, "existing_fact": existing, "reason": f"{pos} vs {neg}"}
                if neg in claim_lower and pos in existing_lower:
                    return {"new_claim": claim.fact, "existing_fact": existing, "reason": f"{neg} vs {pos}"}
        return None

    def _load_kb_facts(self) -> list[str]:
        if not self.db_path.exists():
            return []
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                rows = conn.execute("SELECT features_json FROM decision_vectors").fetchall()
                facts = []
                for (fj,) in rows:
                    d = json.loads(fj)
                    f = d.get("fact") or d.get("description") or ""
                    if f:
                        facts.append(f)
                return facts
        except (sqlite3.OperationalError, json.JSONDecodeError):
            return []

    def _load_kb_values(self) -> dict[str, list[float]]:
        """Load numeric values per dimension for σ checks."""
        if not self.db_path.exists():
            return {}
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                rows = conn.execute("SELECT features_json FROM decision_vectors").fetchall()
                by_dim: dict[str, list[float]] = {}
                for (fj,) in rows:
                    d = json.loads(fj)
                    dim = d.get("dimension", "failure_rates")
                    val = d.get("value")
                    if val is not None:
                        try:
                            by_dim.setdefault(dim, []).append(float(val))
                        except (TypeError, ValueError):
                            pass
                return by_dim
        except (sqlite3.OperationalError, json.JSONDecodeError):
            return {}

"""
SatiationDetector — decides when a hunger cycle should STOP, SLOW_DOWN, or WAKE_UP.
Reads hunger_log and domain_coverage tables from decision-vectors.db.
"""

import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

ROOT = Path(__file__).resolve().parents[4]
VECTORS_DB = ROOT / ".claude" / "data" / "knowledge-distillation" / "decision-vectors.db"

MAX_CALLS_PER_CYCLE = 50
COVERAGE_STOP_THRESHOLD = 0.90
CONFIDENCE_STOP_THRESHOLD = 0.80
SLOW_DOWN_FACT_RATE = 1  # fewer than 1 new fact per 5 calls
WAKE_UP_STALENESS_DAYS = 90


class SatiationDetector:
    def __init__(self, db_path: Optional[Path] = None):
        self.db_path = db_path or VECTORS_DB

    def check(self, domain: str, calls_made: int = 0) -> str:
        """
        Returns: 'STOP' | 'SLOW_DOWN' | 'WAKE_UP' | 'CONTINUE'
        """
        if calls_made >= MAX_CALLS_PER_CYCLE:
            return "STOP"

        if self._should_wake_up(domain):
            return "WAKE_UP"

        coverage = self._get_coverage(domain)
        recent_cycles = self._get_recent_cycles(domain, n=3)

        if self._should_stop(coverage, recent_cycles):
            return "STOP"

        if self._should_slow_down(recent_cycles, calls_made):
            return "SLOW_DOWN"

        return "CONTINUE"

    def _should_stop(self, coverage: dict, recent_cycles: list[dict]) -> bool:
        """ALL three conditions must be true to STOP."""
        cov_pct = self._compute_coverage_pct(coverage)
        if cov_pct < COVERAGE_STOP_THRESHOLD:
            return False

        avg_conf = coverage.get("avg_confidence", 0.0) or 0.0
        if avg_conf < CONFIDENCE_STOP_THRESHOLD:
            return False

        if len(recent_cycles) < 3:
            return False

        total_new = sum(c.get("facts_added", 0) for c in recent_cycles[-3:])
        if total_new > 0:
            return False

        return True

    def _should_slow_down(self, recent_cycles: list[dict], calls_made: int) -> bool:
        """New fact rate < 1 per 5 calls across recent cycles."""
        if calls_made < 5:
            return False
        total_facts = sum(c.get("facts_added", 0) for c in recent_cycles)
        total_calls = sum(c.get("calls_made", 1) for c in recent_cycles) or calls_made
        if total_calls == 0:
            return False
        rate = total_facts / total_calls
        return rate < (SLOW_DOWN_FACT_RATE / 5.0)

    def _should_wake_up(self, domain: str) -> bool:
        """Wake up if domain hasn't been fed in WAKE_UP_STALENESS_DAYS days."""
        coverage = self._get_coverage(domain)
        last_fed = coverage.get("last_fed")
        if not last_fed:
            return True
        try:
            fed_dt = datetime.fromisoformat(last_fed)
            if fed_dt.tzinfo is None:
                fed_dt = fed_dt.replace(tzinfo=timezone.utc)
            days = (datetime.now(timezone.utc) - fed_dt).days
            return days > WAKE_UP_STALENESS_DAYS
        except (ValueError, TypeError):
            return True

    def _compute_coverage_pct(self, coverage: dict) -> float:
        total = max(1, coverage.get("dimensions_total") or 8)
        filled = coverage.get("dimensions_filled") or 0
        return filled / total

    def _get_coverage(self, domain: str) -> dict:
        if not self.db_path.exists():
            return {}
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                conn.row_factory = sqlite3.Row
                row = conn.execute(
                    "SELECT * FROM domain_coverage WHERE domain=?", (domain,)
                ).fetchone()
                return dict(row) if row else {}
        except sqlite3.OperationalError:
            return {}

    def _get_recent_cycles(self, domain: str, n: int = 3) -> list[dict]:
        if not self.db_path.exists():
            return []
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                conn.row_factory = sqlite3.Row
                rows = conn.execute(
                    "SELECT * FROM hunger_log WHERE domain=? ORDER BY id DESC LIMIT ?",
                    (domain, n),
                ).fetchall()
                return [dict(r) for r in rows]
        except sqlite3.OperationalError:
            return []

