    candidates = [("%Y-%m-%d", 10), ("%Y-%m", 7), ("%Y", 4)]
    for fmt, slen in candidates:
        try:
            dt = datetime.strptime(date_str[:slen], fmt)
            dt = dt.replace(tzinfo=timezone.utc)
